begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(7);
insert into auth.users(id,email) values ('ddd70000-0000-4000-8000-000000000001','canvas-a@example.invalid');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ddd70000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.throws_ok($$insert into public.visual_scenes(user_id,id,scene) values ('ddd70000-0000-4000-8000-000000000001','canvas-workspace-v1','{"id":"canvas-workspace-v1","version":1,"format":"canvas-workspace","state":{"documents":[],"conversations":{},"activeId":null}}')$$,'23514',null,'retired module workspace cannot be restored by old clients');
select extensions.throws_ok($$insert into public.visual_scenes(user_id,id,scene) values ('ddd70000-0000-4000-8000-000000000001','empty','{"id":"empty"}')$$,'23514',null,'incomplete primitive scene rejected');
select extensions.throws_ok($$insert into public.visual_scenes(user_id,id,scene) values ('ddd70000-0000-4000-8000-000000000001','bad','{"id":"bad","format":"primitive-scene","schemaVersion":2,"title":"test","updatedAt":"2026-11-14T00:00:00Z","level":"secundaria","variables":[],"primitives":null,"conversation":[] }')$$,'23514',null,'null primitive array cannot bypass the constraint');
select extensions.throws_ok($$insert into public.visual_scenes(user_id,id,scene) values ('ddd70000-0000-4000-8000-000000000001','large',jsonb_build_object('id','large','format','primitive-scene','schemaVersion',2,'title','test','updatedAt','2026-11-14T00:00:00Z','level','secundaria','variables','[]'::jsonb,'primitives','[]'::jsonb,'conversation','[]'::jsonb,'padding',repeat('a',1048576)))$$,'23514',null,'scene larger than 1 MiB rejected');
select extensions.throws_ok($$insert into public.visual_scenes(user_id,id,scene) values ('ddd70000-0000-4000-8000-000000000001','null-format',jsonb_build_object('id','null-format','schemaVersion',2,'format','primitive-scene','title','test','level','secundaria','updatedAt','2026-11-14T00:00:00Z','variables','[]'::jsonb,'primitives','[]'::jsonb,'conversation','[]'::jsonb)||jsonb_build_object('format',null))$$,'23514',null,'null format cannot bypass the contract');
select extensions.throws_ok($$insert into public.visual_scenes(user_id,id,scene) values ('ddd70000-0000-4000-8000-000000000001','null-level',jsonb_build_object('id','null-level','schemaVersion',2,'format','primitive-scene','title','test','level','secundaria','updatedAt','2026-11-14T00:00:00Z','variables','[]'::jsonb,'primitives','[]'::jsonb,'conversation','[]'::jsonb)||jsonb_build_object('level',null))$$,'23514',null,'null level cannot bypass the contract');
reset role;
select extensions.ok(not has_table_privilege('authenticated','public.studio_workspaces','insert'),'retired test table stays inaccessible');
select * from extensions.finish();
rollback;
